package com.gamehub.application.service; import com.gamehub.application.OperationsService; import java.util.List; public final class StationService { private final OperationsService ops; public StationService(OperationsService ops){this.ops=ops;} public List<String> records()throws Exception{return ops.stationRecords();} public long create(long a,String c,String t,String s,long r)throws Exception{return ops.addStation(a,c,t,s,r);} public void update(long a,long id,String t,String s,long r)throws Exception{ops.updateStation(a,id,t,s,r);} public void deactivate(long a,long id)throws Exception{ops.deactivateStation(a,id);} }